def analizar_tipos(datos: list) -> dict:
    """
    Solución pre-respondida de referencia con análisis de inmutabilidad.
    """
    inmutables_tipos = (int, float, str, tuple, bool, bytes)
    conteo_inmutables = 0
    conteo_mutables = 0
    cadenas_limpias = []

    for item in datos:
        if isinstance(item, inmutables_tipos):
            conteo_inmutables += 1
        else:
            conteo_mutables += 1

        if isinstance(item, str):
            cadenas_limpias.append(item.strip().lower())

    return {
        'inmutables': conteo_inmutables,
        'mutables': conteo_mutables,
        'cadenas': cadenas_limpias
    }

