tarea_prerespondida.solucion_referencia:
def filtrar_transacciones(transacciones: list, min_monto: float) -> list:
    """
    Filtra transacciones con complejidad ciclomática mínima O(N).
    """
    if not transacciones or min_monto < 0:
        return []

    aprobadas = []
    for tx in transacciones:
        # Cláusulas de guarda en iteración
        if not isinstance(tx, dict):
            continue
        if tx.get('estado') != 'completada':
            continue
        if tx.get('bloqueado', False):
            continue
        if tx.get('monto', 0) < min_monto:
            continue

        aprobadas.append(tx['id'])

    return aprobadas

