def encontrar_pareja_suma(nums: list, objetivo: int) -> tuple:
    """
    Resuelve Two-Sum en una sola pasada O(N) tiempo y O(N) espacio auxiliar.
    """
    vistos = {}  # {valor: indice}
    for idx, num in enumerate(nums):
        complemento = objetivo - num
        if complemento in vistos:
            return (vistos[complemento], idx)
        vistos[num] = idx
    return ()

